1	// The server the extension talks to. It holds the Anthropic key, which can't
2	// go inside the extension where anyone could read it, finds the checkable
3	// claims in a video's transcript, and checks each claim with web search. It
4	// only listens on this computer. Run with:
5	//   npm run server
6	import {
7	  createServer,
8	  type IncomingMessage,
9	  type ServerResponse,
10	} from "node:http";
11	import {
12	  checkClaim,
13	  costOf,
14	  findClaims,
15	  totals,
16	  type Claim,
17	  type Verdict,
18	} from "./checker.ts";
19	
20	const PORT = 8787;
21	// About six hours of captions, far past any video worth checking claim by claim.
22	const MAX_TRANSCRIPT_CHARS = 400_000;
23	const MAX_BODY_CHARS = 1_000_000;
24	const MAX_CLAIM_CHARS = 1_000;
25	// "Check what was just said" sends about 20 seconds of captions.
26	const MAX_EXCERPT_CHARS = 2_000;
27	// Pressing it costs a claim search plus a check (about 2.3¢), so it can't be
28	// spammed: one at a time, and at most this many an hour.
29	export const PICKS_PER_HOUR = 20;
30	const HOUR_MS = 60 * 60 * 1000;
31	// Twelve checks at once made a third of the searches fail, and the model fell
32	// back on memory (eval/RESULTS.md); two at a time didn't.
33	const PARALLEL_CHECKS = 2;
34	
35	// ponytail: kept in memory, so reloading a video doesn't pay again, and lost
36	// when the server stops; a file or database once people besides Dylan use it.
37	const claimsByVideo = new Map<string, Promise<Claim[]>>();
38	const verdictsByClaim = new Map<string, Promise<Verdict>>();
39	let picking = false;
40	const pickTimes: number[] = [];
41	
42	type Answer = { status: number; body: object };
43	type Route = (body: Record<string, unknown>) => Promise<Answer>;
44	
45	export async function handle(
46	  request: IncomingMessage,
47	  response: ServerResponse,
48	) {
49	  // Web pages send their own Origin; only the extension (or curl) may spend.
50	  const origin = request.headers.origin;
51	  if (origin && !origin.startsWith("chrome-extension://"))
52	    return send(response, 403, { error: "only the extension can use this" });
53	  const route = request.method === "POST" && ROUTES[request.url ?? ""];
54	  if (!route) return send(response, 404, { error: "not found" });
55	
56	  let body: unknown;
57	  try {
58	    body = JSON.parse(await readBody(request));
59	  } catch {
60	    return send(response, 400, { error: "the request wasn't valid JSON" });
61	  }
62	  const answer = await route(
63	    typeof body === "object" && body !== null ? { ...body } : {},
64	  );
65	  send(response, answer.status, answer.body);
66	}
67	
68	const ROUTES: Record<string, Route> = {
69	  "/claims": async ({ videoId, title, transcript }) => {
70	    if (!isVideoId(videoId)) return refuse("missing or malformed video id");
71	    if (typeof title !== "string" || typeof transcript !== "string")
72	      return refuse("missing title or transcript");
73	    if (!transcript.trim()) return refuse("the transcript is empty");
74	    if (transcript.length > MAX_TRANSCRIPT_CHARS)
75	      return {
76	        status: 413,
77	        body: { error: "this video is too long to check" },
78	      };
79	    try {
80	      const claims = await cached(claimsByVideo, videoId, () =>
81	        findClaims(`Title: ${title.slice(0, 300)}\n\n${transcript}`),
82	      );
83	      log(`${claims.length} claims in "${title}"`);
84	      return { status: 200, body: { claims } };
85	    } catch (error) {
86	      return modelFailed(`Finding claims for ${videoId}`, error);
87	    }
88	  },
89	
90	  "/pick": async ({ videoId, title, excerpt }) => {
91	    if (!isVideoId(videoId)) return refuse("missing or malformed video id");
92	    if (typeof title !== "string" || typeof excerpt !== "string")
93	      return refuse("missing title or captions");
94	    if (!excerpt.trim()) return refuse("no captions in the last 20 seconds");
95	    if (excerpt.length > MAX_EXCERPT_CHARS)
96	      return refuse("too many captions to check at once");
97	    const limit = pickLimit(Date.now());
98	    if (limit) return { status: 429, body: { error: limit } };
99	    picking = true;
100	    try {
101	      const claims = await findClaims(
102	        `Title: ${title.slice(0, 300)}
103	
104	${excerpt}`,
105	      );
106	      // ponytail: the last claim is taken as the one the viewer just heard;
107	      // ask the model which one if it picks the wrong one in practice.
108	      const claim = claims.at(-1) ?? null;
109	      log(`Picked: ${claim?.claim ?? "nothing checkable"}`);
110	      return { status: 200, body: { claim } };
111	    } catch (error) {
112	      return modelFailed(`Picking a claim in ${videoId}`, error);
113	    } finally {
114	      picking = false;
115	    }
116	  },
117	
118	  "/check": async ({ videoId, title, claim }) => {
119	    if (!isVideoId(videoId)) return refuse("missing or malformed video id");
120	    if (typeof title !== "string") return refuse("missing title");
121	    const { time, quote, claim: text } = (claim ?? {}) as Partial<Claim>;
122	    if (
123	      typeof time !== "string" ||
124	      typeof quote !== "string" ||
125	      typeof text !== "string" ||
126	      !text.trim() ||
127	      time.length + quote.length + text.length > MAX_CLAIM_CHARS
128	    )
129	      return refuse("missing or malformed claim");
130	    try {
131	      const verdict = await cached(verdictsByClaim, `${videoId} ${text}`, () =>
132	        queuedCheck(() =>
133	          checkClaim({ time, quote, claim: text }, title.slice(0, 300)),
134	        ).then(sourcedOnly),
135	      );
136	      log(`[${time}] ${verdict.verdict}: ${text}`);
137	      return { status: 200, body: { verdict } };
138	    } catch (error) {
139	      return modelFailed(`Checking "${text}"`, error);
140	    }
141	  },
142	};
143	
144	/**
145	 * Why a pick must wait, or null when it may go ahead (and is counted).
146	 * Exported for tests, which pass their own clock.
147	 */
148	export function pickLimit(now: number): string | null {
149	  if (picking) return "still checking the last one";
150	  while (pickTimes.length > 0 && pickTimes[0] <= now - HOUR_MS)
151	    pickTimes.shift();
152	  if (pickTimes.length >= PICKS_PER_HOUR) {
153	    const minutes = Math.ceil((pickTimes[0] + HOUR_MS - now) / 60_000);
154	    return `that's ${PICKS_PER_HOUR} checks this hour; try again in ${minutes} min`;
155	  }
156	  pickTimes.push(now);
157	  return null;
158	}
159	
160	/** No source, no verdict: one without sources rests on the model's memory. */
161	export function sourcedOnly(verdict: Verdict): Verdict {
162	  if (verdict.sources.length > 0 || verdict.verdict === "unverified")
163	    return verdict;
164	  return {
165	    verdict: "unverified",
166	    explanation: "The web search found no sources to check this against.",
167	    sources: [],
168	  };
169	}
170	
171	let running = 0;
172	const waiting: (() => void)[] = [];
173	
174	/** Runs a check once fewer than PARALLEL_CHECKS are running, in arrival order. */
175	export async function queuedCheck<T>(work: () => Promise<T>): Promise<T> {
176	  if (running < PARALLEL_CHECKS) running++;
177	  else await new Promise<void>((resolve) => waiting.push(resolve));
178	  try {
179	    return await work();
180	  } finally {
181	    // Hand the slot straight to the next in line, so no newcomer jumps ahead.
182	    const next = waiting.shift();
183	    if (next) next();
184	    else running--;
185	  }
186	}
187	
188	function cached<T>(
189	  cache: Map<string, Promise<T>>,
190	  key: string,
191	  work: () => Promise<T>,
192	): Promise<T> {
193	  let result = cache.get(key);
194	  if (!result) {
195	    result = work();
196	    cache.set(key, result);
197	    // Forget a failure, so trying again asks again.
198	    result.catch(() => cache.delete(key));
199	  }
200	  return result;
201	}
202	
203	function isVideoId(value: unknown): value is string {
204	  return typeof value === "string" && /^[\w-]{11}$/.test(value);
205	}
206	
207	function refuse(error: string): Answer {
208	  return { status: 400, body: { error } };
209	}
210	
211	function modelFailed(what: string, error: unknown): Answer {
212	  const reason = error instanceof Error ? error.message : String(error);
213	  console.error(`${what} failed: ${reason}`);
214	  return {
215	    status: 502,
216	    body: { error: `the language model failed (${reason.slice(0, 200)})` },
217	  };
218	}
219	
220	function log(line: string) {
221	  console.log(
222	    `${line} · spent since start: about $${costOf(totals).toFixed(3)}`,
223	  );
224	}
225	
226	async function readBody(request: IncomingMessage) {
227	  let body = "";
228	  for await (const chunk of request) {
229	    body += chunk;
230	    if (body.length > MAX_BODY_CHARS) throw new Error("request too large");
231	  }
232	  return body;
233	}
234	
235	function send(response: ServerResponse, status: number, body: object) {
236	  response.writeHead(status, { "Content-Type": "application/json" });
237	  response.end(JSON.stringify(body));
238	}
239	
240	if (import.meta.main) {
241	  createServer((request, response) => {
242	    handle(request, response).catch((error) => {
243	      console.error(error);
244	      if (!response.headersSent) send(response, 500, { error: "server error" });
245	    });
246	  }).listen(PORT, "127.0.0.1", () =>
247	    console.log(`Fact-check server listening on http://127.0.0.1:${PORT}`),
248	  );
249	}
250

