// Finds the checkable claims in a video's transcript and checks each one with
// web search. Shared by the server the extension talks to and by the accuracy
// check in eval/, so both run the prompts that were tested.
import Anthropic from "@anthropic-ai/sdk";
import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
import { z } from "zod";

export const MODEL = "claude-haiku-5-5";
// ponytail: a fixed cap keeps a video's cost predictable (about 17¢ at Haiku
// rates); raise it once long videos need more claims.
const MAX_CLAIMS = 10;
const CHECK_TRIES = 3;

// Haiku 5.5: $0.10 per million input tokens, $0.50 per million output, $10 per
// 1,000 searches.
// ponytail: these rates hold for prompts up to 100K tokens ($0.50 / $2.50
// beyond); price per request from usage if a check's searches grow that large.
const INPUT_PRICE = 0.1;
const OUTPUT_PRICE = 0.5;
const SEARCH_PRICE = 0.01;

export type Usage = { input: number; output: number; searches: number };

/** Dollars spent for the given usage. */
export function costOf(usage: Usage) {
  return (
    (usage.input * INPUT_PRICE + usage.output * OUTPUT_PRICE) / 1e6 +
    usage.searches * SEARCH_PRICE
  );
}

/** Everything spent since this process started. */
export const totals: Usage = { input: 0, output: 0, searches: 0 };
export const searchErrors: string[] = [];

// Created on first use, so importing this file needs no API key (tests don't).
let anthropic: Anthropic | undefined;
const client = () => (anthropic ??= new Anthropic());

const ClaimsSchema = z.object({
  claims: z.array(
    z.object({
      time: z.string(),
      quote: z.string(),
      claim: z.string(),
      kind: z.enum(["fact", "statistic", "forecast", "attributed"]),
    }),
  ),
});
export type Claim = Pick<
  z.infer<typeof ClaimsSchema>["claims"][number],
  "time" | "quote" | "claim"
>;

const VerdictSchema = z.object({
  verdict: z.enum(["supported", "contradicted", "misleading", "unverified"]),
  explanation: z.string(),
  sources: z.array(
    z.object({
      url: z.string(),
      title: z.string(),
      says: z.string(),
      stance: z.enum(["supports", "contradicts", "context"]),
    }),
  ),
});
export type Verdict = z.infer<typeof VerdictSchema>;

const FIND_CLAIMS = `You find the checkable claims in a video transcript for a fact-checker.

A claim counts if a source could support or contradict it today: facts, statistics, dates, and what experts forecast. Leave out opinions, jokes, figures of speech, rhetorical questions, the speaker's plans, and speculation no source could speak to. When someone is quoted, the claim is what they asserted as fact (for example "Collins says she voted against the bill"), not their opinion.

Transcripts are often automatic captions: names may be misspelled and punctuation missing. Write each claim as one standalone sentence with names spelled correctly, so it can be searched without the video. "time" is the timestamp of the line it comes from, and "quote" is the shortest exact span of the transcript it comes from.

Return at most ${MAX_CLAIMS} claims, choosing the ones a viewer would most want checked: specific, consequential, or surprising. Skip near-duplicates.`;

const CHECK_CLAIM = `You check one claim from a video against sources found with web search.

Verdicts:
- supported: reliable sources agree with the claim as stated. A rounded number, or one inside the range experts give, is supported; mention the precise figure in the explanation.
- contradicted: reliable sources say otherwise. When the claim's central specific (a number, timespan, or effect) is wrong, it is contradicted even if a related fact is true; don't soften it to misleading.
- misleading: partly true, but a viewer would come away believing something false, and you can name that false belief. A missing qualifier, nuance the claim leaves out, or a debate among experts the claim takes one mainstream side of, is not enough on its own: if the core of the claim holds, it is supported, and the nuance goes in the explanation. But stretching what's true of one case to a whole group (one oil's history told as all seed oils') is misleading.
- unverified: the sources found don't address it. This is an honest answer, not a failure; prefer it over guessing. But a specific claim that no research supports, where reliable sources say the effect it describes doesn't exist, is contradicted.

Judge the claim as stated, not a stronger version of it: don't call it misleading or contradicted for something it doesn't say (a claim about a person's own ideal isn't a claim about a universal one). Sources must speak to the claim as stated: guidelines or recommendations about what people should do don't contradict a claim about what they actually do. When the claim is that someone said or reported something, judge whether they said it, not whether it is true. For a forecast, judge whether it matches what experts actually forecast. Prefer primary sources, scientific reviews, and established outlets over blogs. Keep the explanation to two sentences a viewer could read mid-video. List only sources you actually found, each with what it says about the claim and its stance: supports, contradicts, or context when it only adds background or is mixed.`;

/** The claims a viewer would most want checked, from a transcript with a "Title:" line. */
export async function findClaims(transcript: string): Promise<Claim[]> {
  const response = await client().messages.parse({
    model: MODEL,
    max_tokens: 16000,
    output_config: { effort: "medium", format: zodOutputFormat(ClaimsSchema) },
    system: FIND_CLAIMS,
    messages: [{ role: "user", content: transcript }],
  });
  addUsage(response.usage);
  if (!response.parsed_output)
    throw new Error(`No claims: ${response.stop_reason}`);
  return response.parsed_output.claims;
}

/** Checks a claim again when its searches failed, so verdicts rest on sources. */
export async function checkClaim(
  claim: Claim,
  videoTitle: string,
): Promise<Verdict> {
  for (let attempt = 1; ; attempt++) {
    const { verdict, failedSearches } = await checkOnce(claim, videoTitle);
    if (failedSearches === 0 || attempt === CHECK_TRIES) {
      if (failedSearches > 0)
        verdict.explanation += ` (${failedSearches} searches failed)`;
      return verdict;
    }
    await new Promise((resolve) => setTimeout(resolve, 5000 * attempt));
  }
}

async function checkOnce(claim: Claim, videoTitle: string) {
  let failedSearches = 0;
  const messages: Anthropic.MessageParam[] = [
    {
      role: "user",
      content: `Video: ${videoTitle}\nClaim (at ${claim.time}): ${claim.claim}\nAs said: "${claim.quote}"`,
    },
  ];
  // Web search can pause a long turn; resend the paused turn to let it finish.
  for (let attempt = 0; attempt < 4; attempt++) {
    const response = await client().messages.parse({
      model: MODEL,
      max_tokens: 16000,
      output_config: {
        effort: "medium",
        format: zodOutputFormat(VerdictSchema),
      },
      system: CHECK_CLAIM,
      // The 2026-02-09 search (with filtering) is for Opus and Sonnet only.
      tools: [{ type: "web_search_20250305", name: "web_search", max_uses: 5 }],
      messages,
    });
    addUsage(response.usage);
    // A failed search comes back as an error object instead of a result list.
    for (const block of response.content) {
      if (
        block.type === "web_search_tool_result" &&
        !Array.isArray(block.content)
      ) {
        failedSearches++;
        searchErrors.push(block.content.error_code);
      }
    }
    if (response.stop_reason === "pause_turn") {
      messages.push({ role: "assistant", content: response.content });
      continue;
    }
    if (!response.parsed_output)
      throw new Error(`No verdict: ${response.stop_reason}`);
    return { verdict: response.parsed_output, failedSearches };
  }
  throw new Error("Still paused after 4 tries");
}

function addUsage(usage: Anthropic.Usage) {
  totals.input += usage.input_tokens + (usage.cache_read_input_tokens ?? 0);
  totals.output += usage.output_tokens;
  totals.searches += usage.server_tool_use?.web_search_requests ?? 0;
}
// The background service worker carries the content script's requests to the
// local server, which holds the API keys. The content script can't call it
// itself: its requests count as the YouTube page's, and Chrome keeps web pages
// away from this computer's own servers.
import { ENABLED_KEY, readEnabled, type ServerRequest } from "./messages.ts";

// Clicking the icon turns the extension on or off; the content script on each
// YouTube tab hears the change and hides or shows itself.
// Clicks wait their turn, so a quick double click turns it off and on again
// rather than both clicks reading "on" and writing "off".
let lastToggle = Promise.resolve();
chrome.action.onClicked.addListener(() => {
  lastToggle = lastToggle.then(async () => {
    await chrome.storage.local.set({ [ENABLED_KEY]: !(await readEnabled()) });
  });
});
chrome.storage.onChanged.addListener((changes) => {
  if (ENABLED_KEY in changes) void showOnOff();
});
// Chrome forgets the badge, its colour, and the tooltip when it restarts.
chrome.runtime.onStartup.addListener(() => void showOnOff());
chrome.runtime.onInstalled.addListener(() => void showOnOff());

async function showOnOff() {
  const enabled = await readEnabled();
  await chrome.action.setBadgeBackgroundColor({ color: "#5f6368" });
  await chrome.action.setBadgeText({ text: enabled ? "" : "OFF" });
  await chrome.action.setTitle({
    title: enabled
      ? "Video Fact Check is on. Click to turn it off."
      : "Video Fact Check is off. Click to turn it on.",
  });
}

// Plain HTTP is fine here: the request never leaves this computer.
const SERVER = "http://127.0.0.1:8787";
const PATHS: Record<ServerRequest["type"], string> = {
  findClaims: "/claims",
  checkClaim: "/check",
  pickClaim: "/pick",
};

chrome.runtime.onMessage.addListener(
  (message: Partial<ServerRequest>, _sender, sendResponse) => {
    const path = message.type && PATHS[message.type];
    if (!path) return false;
    const { type: _type, ...body } = message;
    void askServer(path, body).then(sendResponse);
    return true; // Keeps the channel open until sendResponse is called.
  },
);

async function askServer(path: string, body: object) {
  let response: Response;
  try {
    response = await fetch(`${SERVER}${path}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
  } catch {
    return {
      ok: false,
      error:
        "couldn't reach the fact-check server. Is it running? (npm run server)",
    };
  }
  const answer = await response.json().catch(() => ({}));
  return response.ok
    ? { ok: true, ...answer }
    : {
        ok: false,
        error: answer.error ?? `the server answered ${response.status}`,
      };
}
import assert from "node:assert/strict";
import { once } from "node:events";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { after, test } from "node:test";
import {
  handle,
  PICKS_PER_HOUR,
  pickLimit,
  queuedCheck,
  sourcedOnly,
} from "../server/main.ts";

// These requests are all refused before the language model is called, so the
// tests spend nothing and need no API key.
const server = createServer(
  (request, response) => void handle(request, response),
);
server.listen(0, "127.0.0.1");
await once(server, "listening");
const { port } = server.address() as AddressInfo;
after(() => server.close());

function ask(path: string, origin: string, body: object) {
  return fetch(`http://127.0.0.1:${port}${path}`, {
    method: "POST",
    headers: { Origin: origin, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

const request = {
  videoId: "hmkoFDMAvkc",
  title: "A video",
  transcript: "[0:00] hi",
};

test("web pages can't spend credits through the server", async () => {
  const response = await ask("/claims", "https://example.com", request);
  assert.equal(response.status, 403);
});

test("an empty transcript is refused before anything is spent", async () => {
  const response = await ask("/claims", "chrome-extension://abc", {
    ...request,
    transcript: "   ",
  });
  assert.equal(response.status, 400);
  assert.deepEqual(await response.json(), { error: "the transcript is empty" });
});

test("a claim to check needs its text", async () => {
  const response = await ask("/check", "chrome-extension://abc", {
    videoId: "hmkoFDMAvkc",
    title: "A video",
    claim: { time: "4:31", quote: "about 3 years", claim: " " },
  });
  assert.equal(response.status, 400);
});

# Video Fact Check

A Chrome extension that fact-checks YouTube videos as you watch: it reads a
video's captions, finds the checkable claims, and (soon) checks each against
sources, live. See `PLAN.md` for where the project stands and `RESEARCH.md`
for why it is built this way.

Current state: on a YouTube video, a toggle in the player's controls finds the
claims worth checking ("Finding claims…", then "9 claims"); clicking it lists
them beside the video, and clicking a claim jumps to it. Checking them against
sources comes next.

It has two parts: the extension, and a small server on your own computer that
holds the Anthropic API key (it can't go inside the extension, where anyone
could read it) and asks Claude for the claims.

## Requirements

- [Node.js](https://nodejs.org/) 24 or newer (it runs TypeScript directly)
- Google Chrome
- An Anthropic API key in a `.env` file in this folder:
  `ANTHROPIC_API_KEY=...` (Git ignores `.env`)

## Build

```bash
npm install
npm run build
```

The built scripts land in `extension/dist/`. Use `npm run watch` to rebuild on
every save.

## Run the server

```bash
npm run server
```

Leave it running while you watch. It listens only on this computer
(`http://127.0.0.1:8787`), answers only the extension, and prints what each
video cost. Finding a video's claims costs well under a cent; it remembers
them until it stops, so reloading a video doesn't pay again.

## Load it in Chrome

1. Open `chrome://extensions`.
2. Turn on **Developer mode** (top right).
3. Click **Load unpacked** and choose this project's `extension` folder.
4. After rebuilding, click the reload arrow on the extension's card, then
   reload the YouTube tab.

## Try it

Open a YouTube video with captions, such as
[this seed-oil video](https://www.youtube.com/watch?v=hmkoFDMAvkc). The toggle
appears next to the settings gear in the player's controls (move the mouse over
the video to show them). If it says "Couldn't check: retry", hover over it to
see why; usually the server isn't running.

## Develop

```bash
npm test           # unit tests
npm run typecheck  # TypeScript checks
npm run format     # format with Prettier
```

Code that depends on how YouTube's site is built lives in `src/page-hook.ts`
(reading captions through YouTube's player) and `src/content.ts` (where the
toggle and the list go). When YouTube changes its site, start there.

## Promo trailer

`promo/` holds a 36-second trailer made with [Remotion](https://www.remotion.dev/)
(videos written as React code). It shows the planned design and is labeled
"Concept preview" until those features exist. It has its own dependencies:

```bash
cd promo
npm install
npm run studio   # live preview with sound in the browser
npm run render   # writes out/trailer.mp4 (1080p, with soundtrack)
npm run poster   # writes out/poster.png
```

The script and timing live in `promo/src/timeline.ts`; the soundtrack is
synthesized by `promo/scripts/soundtrack.ts` from the same timeline, so sound
effects stay in sync when timing changes. Rendering needs Google Chrome
installed (see `promo/remotion.config.ts`).

## Accuracy check

`eval/check.ts` finds the checkable claims in a saved transcript and checks
each one with Claude and web search, writing a report to `eval/results/`. It
uses the same prompts as the server (`server/checker.ts`), needs
`ANTHROPIC_API_KEY` in `.env`, and costs about $0.17 per video with Haiku.

```bash
npm run check-claims -- eval/transcripts/<name>.txt
```

Transcripts are kept out of Git; results and grades are in `eval/RESULTS.md`.

