        ),
      ];
    case "noCaptions":
      return [
        note(
          "This video has no captions, so there's nothing to read claims from.",
        ),
      ];
    case "error": {
      const { retry } = status;
      const button = element("button", "Try again", "vfc-action");
      button.type = "button";
